package com.portfolio.features.education.controller; import com.portfolio.common.api.ApiResponse; import com.portfolio.features.education.dto.*; import com.portfolio.features.education.mapper.EducationMapper; import com.portfolio.features.education.service.EducationService; import com.portfolio.features.user.service.UserService; import jakarta.validation.Valid; import java.util.*; import lombok.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/educations") @RequiredArgsConstructor public class EducationController {private final EducationService service;private final UserService users;private final EducationMapper mapper;@GetMapping public ApiResponse<List<EducationResponse>> list(@AuthenticationPrincipal Jwt j){return ApiResponse.success("Educations retrieved successfully.",service.list(users.synchronize(j)).stream().map(mapper::toResponse).toList());}@PostMapping public ApiResponse<EducationResponse> create(@AuthenticationPrincipal Jwt j,@Valid @RequestBody EducationRequest r){return ApiResponse.success("Education created successfully.",mapper.toResponse(service.create(users.synchronize(j),r)));}@PutMapping("/{id}") public ApiResponse<EducationResponse> update(@AuthenticationPrincipal Jwt j,@PathVariable UUID id,@Valid @RequestBody EducationRequest r){return ApiResponse.success("Education updated successfully.",mapper.toResponse(service.update(users.synchronize(j),id,r)));}@DeleteMapping("/{id}") public ApiResponse<Void> delete(@AuthenticationPrincipal Jwt j,@PathVariable UUID id){service.delete(users.synchronize(j),id);return ApiResponse.success("Education deleted successfully.",null);}}
